class Helpers(unittest.TestCase):
    def test_bounded_int(self):
        from stockroom.parsing import MAX_QUANTITY, bounded_int

        self.assertEqual(bounded_int("+7"), 7)
        self.assertEqual(bounded_int("-007"), -7)
        self.assertEqual(bounded_int(str(MAX_QUANTITY)), MAX_QUANTITY)
        self.assertIsNone(bounded_int(str(MAX_QUANTITY + 1)))
        self.assertIsNone(bounded_int("-" + BIG))

    def test_amount_is_exact_for_decimals(self):
        from decimal import Decimal

        from stockroom.cli import _amount

        self.assertEqual(_amount(Decimal("123456789012345678901.01")), "123456789012345678901.01")
        self.assertEqual(_amount(Decimal("-0.00")), "0.00")


